#!/usr/bin/env python3
"""Build AmiHASS locale files from locale/amihass.cd and locale/<language>.ct.

Writes include/ah_strings.h (IDs and built-in English) and
Catalogs/<language>/amihass.catalog (IFF CTLG, ISO-8859-1) for each .ct.
--check only verifies that the generated files are current."""
import re, struct, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
SPEC = re.compile(r'%[-+ #0]*\d*(?:\.\d+)?(?:l|h)?[sdlux]')

def parse_cd(text):
    out, lines, i = [], text.splitlines(), 0
    while i < len(lines):
        line = lines[i]
        m = re.match(r'^(MSG_[A-Z0-9_]+) \((\d+)//\)$', line)
        if m:
            if i + 2 >= len(lines) or lines[i + 2] != ';':
                raise ValueError('entry %s must be one line then ;' % m.group(1))
            out.append((m.group(1), int(m.group(2)), lines[i + 1])); i += 3; continue
        if line and not line.startswith((';', '#')):
            raise ValueError('unexpected line in .cd: ' + line)
        i += 1
    names = [n for n, _, _ in out]; ids = [x for _, x, _ in out]
    if len(set(names)) != len(names) or len(set(ids)) != len(ids):
        raise ValueError('duplicate names or IDs in .cd')
    return out

def parse_ct(text):
    meta, strings, lines, i = {}, {}, text.splitlines(), 0
    while i < len(lines):
        line = lines[i]
        if line.startswith('## '):
            key, _, value = line[3:].partition(' '); meta[key] = value.strip(); i += 1; continue
        if line.startswith('MSG_'):
            if i + 2 >= len(lines) or lines[i + 2] != ';':
                raise ValueError('translation %s must be one line then ;' % line)
            strings[line] = lines[i + 1]; i += 3; continue
        if line and not line.startswith(';'):
            raise ValueError('unexpected line in .ct: ' + line)
        i += 1
    return meta, strings

def c_string(s):
    return '"' + ''.join('\\x%02x""' % ord(ch) if ord(ch) > 126 or ord(ch) < 32 else ('\\' + ch if ch in '"\\' else ch) for ch in s) + '"'

def header(entries):
    rows = ['/* Generated by tools/make_catalogs.py from locale/amihass.cd - do not edit. */',
            '#ifndef AH_STRINGS_H', '#define AH_STRINGS_H']
    for name, ident, text in entries:
        text.encode('latin-1')
        rows.append('#define %s %d' % (name, ident))
        rows.append('#define %s_STR %s' % (name, c_string(text)))
    rows += ['#define AH_TR(name) ah_tr(name,name##_STR)', '#endif', '']
    return '\n'.join(rows)

def chunk(kind, data):
    return kind + struct.pack('>I', len(data)) + data + (b'\0' if len(data) & 1 else b'')

def catalog(entries, meta, strings, language, extra=()):
    body = b''
    items = [(ident, english, strings[name]) for name, ident, english in entries if name in strings]
    items += [(ident, english, text) for english, ident, text in extra]
    for ident, english, text in items:
        name = str(ident)
        if SPEC.findall(text) != SPEC.findall(english):
            raise ValueError('%s: %s must keep the format codes of %r' % (language, name, english))
        data = text.encode('latin-1') + b'\0'
        body += struct.pack('>II', ident, len(data)) + data + b'\0' * ((4 - len(data) % 4) % 4)
    form = b'CTLG' + chunk(b'FVER', meta['version'].encode('latin-1') + b'\0') + chunk(b'LANG', meta['language'].encode('latin-1') + b'\0') + chunk(b'STRS', body)
    return b'FORM' + struct.pack('>I', len(form)) + form

# Window text reached through the panel and GadTools helpers is looked up by
# its English text (ah_tx). These files are scanned for it; data files
# (sample names, layouts, actions sent to the service) are not.
UI_FILES = ('attribute_view.c', 'browser.c', 'camera_view.c', 'camera_thumbs.c', 'connectivity.c', 'dashboard.c', 'dashboard_picker.c', 'log_view.c', 'panel.c', 'preferences.c', 'ui.c', 'catalogue_picker.c', 'info.c', 'browser_live.c', 'keypad.c')
LITERAL = re.compile(r'"((?:[^"\\\n]|\\.)*)"')
SKIP = re.compile(r'^(QA|PASS|FAIL|SELFTEST|DEBUG)\b|ENV|T:|SYS:|RAM:|LOCALE|PROGDIR|\.library|\.device|\.catalog|\.cfg|\.info|/api|https?:|topaz|AmiHASS\.|\$VER|\\n|\\"|[{}]|^C:|^#?%[^ ]*$|^[a-z_0-9]+(\.[a-z_0-9]+)*$|^[A-Z_0-9.]+$|^(Brightness|Volume|Temperature|Color|Position|Value|Humidity|Option|HVAC) %')
def c_unescape(text):
    return re.sub(r'\\(x[0-9a-fA-F]{2}|[0-7]{1,3}|.)', lambda m: chr(int(m.group(1)[1:], 16)) if m.group(1)[0] == 'x' else chr(int(m.group(1), 8)) if m.group(1)[0].isdigit() else {'n': '\n', 't': '\t'}.get(m.group(1), m.group(1)), text)
def ui_strings():
    found = []
    for name in UI_FILES:
        for raw in LITERAL.findall((ROOT / 'src' / name).read_text(encoding='latin-1')):
            text = c_unescape(raw)
            if len(text) < 2 or not re.search('[A-Za-z]{2}', text) or SKIP.search(raw) or text in found:
                continue
            found.append(text)
    return found
def parse_tsv(text):
    rows = []
    for line in text.splitlines():
        if not line or line.startswith('#'):
            continue
        parts = line.split('\t')
        if len(parts) != 3:
            raise ValueError('texts.tsv needs english<TAB>svenska<TAB>deutsch: ' + line)
        rows.append(parts)
    return rows
def texts_header(rows):
    table = sorted((english, 1000 + i) for i, (english, _, _) in enumerate(rows))
    out = ['/* Generated by tools/make_catalogs.py from locale/texts.tsv - do not edit. */', '#ifndef AH_TEXTS_H', '#define AH_TEXTS_H',
           '/* English window text and its catalog ID, sorted for binary search (strcmp). */',
           'static const struct {const char *text;long id;} ah_text_table[]={']
    out += ['{%s,%d},' % (c_string(english), ident) for english, ident in table]
    out += ['};', '#endif', '']
    return '\n'.join(out)
def build():
    entries = parse_cd((ROOT / 'locale/amihass.cd').read_text())
    rows = parse_tsv((ROOT / 'locale/texts.tsv').read_text(encoding='utf-8'))
    english = [r[0] for r in rows]
    if len(set(english)) != len(english):
        raise ValueError('texts.tsv has duplicate English text')
    for column, language in ((1, 'svenska'), (2, 'deutsch')):
        for r in rows:
            if not r[column] or SPEC.findall(r[column]) != SPEC.findall(r[0]):
                raise ValueError('texts.tsv %s: %r needs a translation with the same format codes' % (language, r[0]))
    outputs = {ROOT / 'include/ah_strings.h': header(entries).encode('latin-1'), ROOT / 'include/ah_texts.h': texts_header(rows).encode('latin-1')}
    known = {n for n, _, _ in entries}
    for ct in sorted((ROOT / 'locale').glob('*.ct')):
        meta, strings = parse_ct(ct.read_text(encoding='utf-8'))
        unknown = set(strings) - known
        if unknown:
            raise ValueError('%s: unknown %s' % (ct.name, ', '.join(sorted(unknown))))
        missing = known - set(strings)
        if missing:
            raise ValueError('%s: missing %s' % (ct.name, ', '.join(sorted(missing))))
        column = {'svenska': 1, 'deutsch': 2}.get(meta['language'])
        extra = [(r[0], 1000 + i, r[column]) for i, r in enumerate(rows)] if column else []
        outputs[ROOT / 'Catalogs' / meta['language'] / 'amihass.catalog'] = catalog(entries, meta, strings, ct.stem, extra)
    return outputs

if __name__ == '__main__':
    if '--extract' in sys.argv:
        path = ROOT / 'locale/texts.tsv'
        rows = parse_tsv(path.read_text(encoding='utf-8')) if path.exists() else []
        known = {r[0] for r in rows}
        new = [t for t in ui_strings() if t not in known and '\t' not in t and '\n' not in t]
        print('\n'.join(new))
        sys.exit(0)
    outputs = build()
    if '--check' in sys.argv:
        stale = [str(p.relative_to(ROOT)) for p, data in outputs.items() if not p.is_file() or p.read_bytes() != data]
        if stale:
            sys.exit('Out of date: ' + ', '.join(stale) + ' (run tools/make_catalogs.py)')
        print('Catalogs current: %d strings, %d languages' % (len(parse_cd((ROOT / 'locale/amihass.cd').read_text())), len(outputs) - 1))
    else:
        for p, data in outputs.items():
            p.parent.mkdir(parents=True, exist_ok=True); p.write_bytes(data)
        print('Wrote', ', '.join(str(p.relative_to(ROOT)) for p in outputs))
